<style>.sf-admin-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(240px,1fr);gap:24px}.sf-admin-card{padding:24px;background:var(--mp-surface,#fff);border:1px solid var(--mp-border,#dce3df);border-radius:12px;margin-bottom:20px}.sf-admin-card label{display:block;font-size:13px;margin:18px 0 8px}.sf-admin-card input:not([type=checkbox]):not([type=radio]),.sf-admin-card textarea{width:100%;box-sizing:border-box;padding:11px;border:1px solid var(--mp-border,#dce3df);border-radius:5px;font:inherit;background:transparent;color:inherit}.sf-admin-card input[type=checkbox],.sf-admin-card input[type=radio]{margin-right:8px}.sf-admin-card p{font-size:13px;line-height:1.7}.sf-admin-card button,.sf-admin-action{display:inline-block;border:0;border-radius:6px;padding:12px 18px;background:var(--mp-primary,#24553c);color:#fff;text-decoration:none;cursor:pointer;font:inherit;font-size:13px}.sf-admin-notice{padding:16px;border:1px solid #b2d2bf;background:#eff9f2;margin-bottom:20px}.sf-admin-error{background:#fff0ea;border-color:#e3b4a2}.sf-admin-links{display:flex;gap:20px;flex-wrap:wrap;font-size:13px;margin:20px 0}.sf-admin-article{padding:16px 0;border-bottom:1px solid var(--mp-border,#dce3df)}@media(max-width:760px){.sf-admin-grid{grid-template-columns:1fr}.sf-admin-card{padding:18px}}</style>
